parameters.jsCode:
const input=$json??{};
const pkg=input.closingPackage??input.package??{};
const agreement=input.agreement??input.contract??{};
const parties=input.parties??{};
const docs=Array.isArray(pkg.documents)?pkg.documents:(Array.isArray(input.documents)?input.documents:[]);
const requiredDocs=Array.isArray(input.requiredDocuments)?input.requiredDocuments:(Array.isArray(pkg.requiredDocuments)?pkg.requiredDocuments:[]);
const verifiedDocs=new Set(docs.filter(d=>d.verified===true||d.status==='verified').map(d=>String(d.type??d.name??'').toLowerCase()));
const missingDocs=requiredDocs.map(d=>String(d.type??d.name??d).toLowerCase()).filter(d=>!verifiedDocs.has(d));
const executed=Boolean(input.executedAgreementVerified??agreement.executed===true);
const signed=Boolean(input.signedEvidenceVerified??agreement.signed===true);
const identity=Boolean(input.identityVerified??input.identityVerifiedAllParties??false);
const agreementType=String(input.agreementType??agreement.type??'').trim();
const closingDate=input.closingDate??pkg.closingDate??null;
const closingDateValid=Boolean(closingDate&&!Number.isNaN(new Date(closingDate).getTime()));
const price=Number(input.agreedPrice??agreement.agreedPrice??NaN);
const mao=Number(input.effectiveMAO??agreement.effectiveMAO??NaN);
const priceProtected=Number.isFinite(price)&&Number.isFinite(mao)&&price<=mao;
const blockerList=Array.isArray(input.blockers)?input.blockers.filter(Boolean):[];
const partyIds=Array.isArray(parties.required)?parties.required:[]; const suppliedPartyIds=Array.isArray(parties.verified)?parties.verified:[];
const missingParties=partyIds.filter(x=>!suppliedPartyIds.includes(x));
const gaps=[];
if(!executed)gaps.push('executed_agreement');
if(!signed)gaps.push('signed_evidence');
if(!identity)gaps.push('party_identity_verification');
if(!agreementType)gaps.push('agreement_type');
if(!closingDateValid)gaps.push('valid_closing_date');
if(!priceProtected)gaps.push('agreed_price_at_or_below_effective_MAO');
if(missingDocs.length)gaps.push('required_documents');
if(missingParties.length)gaps.push('required_parties');
if(blockerList.length)gaps.push('blockers_cleared');

let status='package_ready';
if(blockerList.length)status='blocked';
else if(gaps.length)status='package_incomplete';

const route=status==='package_ready'?'WF-177':status==='package_incomplete'?'WF-176':'WF-126';
return [{json:{...input,workflow:'WF-182',closing_package_validation:{status,missing_requirements:gaps,missing_documents:missingDocs,missing_parties:missingParties,document_count:docs.length,required_document_count:requiredDocs.length,closing_date:closingDate,price_protected:priceProtected},routing:{next_workflow:route,reason:status,requires_human_review:status==='blocked'},audit:{event:'final_closing_package_validation_evaluated',status,requirement_gap_count:gaps.length}}}];

